Socket? currentSocket; // reconnect 時指向最新 Socket

async Task ReceiveGenerationAsync(Socket socket, int generation, CancellationToken ct)
{
    try
    {
        await ReceiveLoopAsync(socket, ct); // 此工作讀的是傳入的 socket
    }
    finally
    {
        currentSocket?.Dispose();            // 錯：finally 時欄位可能已是新 Socket
        SetStatus(ConnectionState.Disconnected); // 錯：沒有核對目前 generation
    }
}

// 新連線成功後：currentSocket = socket18; generation = 18;
// 遲到的 g17 finally 讀到 currentSocket 時，目標已是 socket18。
